23	// The canonical drain templates (what builtin_qemu() and vsim --describe ship).
24	const std::vector<std::string> kQemuFastLeg = {
25	    "{bin}",
26	    "-object", "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
27	    "-machine", "andes_ae350,memory-backend=mem",
28	    "-cpu", "andes-ax45mpv,vlen=512",
29	    "-nographic",
30	    "-semihosting-config", "enable=on,target=native",
31	    "-bios", "{elf}",
32	    "-plugin", "{plugin},outfile={state_out}",
33	};
34	
35	const std::vector<std::string> kVsimAccurateLeg = {
36	    "{bin}", "{elf}",
37	    "--resume-from-qemu", "{state_in}",
38	    "--handoff-out", "{state_out}",
39	    "--shared-mem-path", "{mmap}",
40	    "--shared-mem-size", "{mmap_size}",
