54	void check_eq(const std::vector<std::string>& got,
55	              const std::vector<std::string>& want, const char* label) {
56	  CHECK(got.size() == want.size());
57	  const size_t n = got.size() < want.size() ? got.size() : want.size();
58	  for (size_t i = 0; i < n; ++i) {
59	    if (got[i] != want[i])
60	      std::fprintf(stderr, "  %s[%zu]: got '%s' want '%s'\n", label, i,
61	                   got[i].c_str(), want[i].c_str());
62	    CHECK(got[i] == want[i]);
63	  }
64	}
