68	int main() {
69	  // --- build_argv: every placeholder filled, including substring + repeat ---
70	  {
71	    std::string err;
72	    std::map<std::string, std::string> ctx = {
73	        {"bin", "/q"},      {"elf", "/e"},     {"plugin", "/p"},
74	        {"mmap", "/m"},     {"mmap_size", "134217728"}, {"state_out", "/s0"},
75	    };
76	    std::vector<std::string> got = build_argv(kQemuFastLeg, ctx, err);
77	    CHECK(err.empty());
78	    check_eq(got,
79	             {"/q", "-object",
80	              "memory-backend-file,id=mem,share=on,mem-path=/m,size=134217728",
81	              "-machine", "andes_ae350,memory-backend=mem", "-cpu",
82	              "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
83	              "enable=on,target=native", "-bios", "/e", "-plugin",
84	              "/p,outfile=/s0"},
85	             "qemu");
86	  }
87	  {
88	    std::string err;
89	    std::map<std::string, std::string> ctx = {
90	        {"bin", "/v"},  {"elf", "/e"},  {"state_in", "/s0"},
91	        {"state_out", "/s1"}, {"mmap", "/m"}, {"mmap_size", "134217728"},
92	        {"mmap_base", "0x0"},
93	    };
94	    std::vector<std::string> got = build_argv(kVsimAccurateLeg, ctx, err);
95	    CHECK(err.empty());
96	    check_eq(got,
97	             {"/v", "/e", "--resume-from-qemu", "/s0", "--handoff-out", "/s1",
98	              "--shared-mem-path", "/m", "--shared-mem-size", "134217728",
99	              "--shared-mem-base", "0x0"},
100	             "vsim");
101	  }
102	  // a repeated placeholder expands every occurrence
103	  {
104	    std::string err;
105	    std::vector<std::string> got =
106	        build_argv({"a={x},b={y},a2={x}"}, {{"x", "1"}, {"y", "2"}}, err);
107	    CHECK(err.empty());
108	    check_eq(got, {"a=1,b=2,a2=1"}, "repeat");
109	  }
110	  // an unknown placeholder is an error, not a silent empty fill
111	  {
112	    std::string err;
113	    std::vector<std::string> got = build_argv({"{bogus}"}, {{"x", "1"}}, err);
114	    CHECK(got.empty());
115	    CHECK(!err.empty());
116	  }
117	
118	  // --- plan_argvs: thread state files across a 2-step hybrid plan ---
119	  std::vector<EngineDescriptor> engines = {
120	      fake("qemu", "/qbin", "fast-leg", kQemuFastLeg),
121	      fake("verilator:test", "/vbin", "accurate-leg", kVsimAccurateLeg),
122	  };
123	  Plan plan;
124	  plan.elf = "/e";
125	  plan.mem_size = 134217728;
126	  plan.steps = {
127	      {"qemu", "fast-leg", {"csr", {}}},
128	      {"verilator:test", "accurate-leg", {"csr", {}}},
129	  };
130	  RuntimeCtx rc;
131	  rc.mmap_path = "/mm";
132	  rc.mem_size = 134217728;
133	  rc.mmap_base = "0x0";
134	  rc.plugin_path = "/pl";
135	
136	  {
137	    std::string err;
138	    std::vector<std::vector<std::string>> argvs =
139	        plan_argvs(plan, engines, "/wd", rc, err);
140	    CHECK(err.empty());
141	    CHECK(argvs.size() == 2);
142	    if (argvs.size() == 2) {
143	      // step 0 (qemu): drains to state-0.bin; no state_in referenced
144	      check_eq(argvs[0],
145	               {"/qbin", "-object",
146	                "memory-backend-file,id=mem,share=on,mem-path=/mm,size=134217728",
147	                "-machine", "andes_ae350,memory-backend=mem", "-cpu",
148	                "andes-ax45mpv,vlen=512", "-nographic", "-semihosting-config",
149	                "enable=on,target=native", "-bios", "/e", "-plugin",
150	                "/pl,outfile=/wd/state-0.bin"},
151	               "step0");
152	      // step 1 (vsim): resumes from step 0's drain, drains to state-1.bin
153	      check_eq(argvs[1],
154	               {"/vbin", "/e", "--resume-from-qemu", "/wd/state-0.bin",
155	                "--handoff-out", "/wd/state-1.bin", "--shared-mem-path", "/mm",
156	                "--shared-mem-size", "134217728", "--shared-mem-base", "0x0"},
157	               "step1");
158	    }
159	  }
160	  // unknown engine id is an error
161	  {
162	    Plan bad = plan;
163	    bad.steps[0].engine_id = "nope";
164	    std::string err;
165	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
166	    CHECK(!err.empty());
167	  }
168	  // a role the engine has no template for is an error
169	  {
170	    Plan bad = plan;
171	    bad.steps[1].role = "no-such-role";
172	    std::string err;
173	    CHECK(plan_argvs(bad, engines, "/wd", rc, err).empty());
174	    CHECK(!err.empty());
175	  }
176	
177	  return andes_sim::test::report("plan");
178	}
