1	// F6 integration acceptance: a real 2-step hybrid plan, end to end.
2	//
3	// Unlike plan_test.cpp (pure, fake descriptors), this discovers the real
4	// engines, builds a csr-trigger [qemu fast-leg -> verilator accurate-leg] plan
5	// on a fixture ELF, and runs it through run_plan -- spawning actual QEMU + vsim
6	// and threading the drained hybrid_state_v1 between them. It asserts the
7	// done-when: the plan succeeds and the vsim leg's mcycle exceeds the qemu leg's
8	// (vsim restores qemu's mcycle then counts real cycles, so the delta is the
9	// measured kernel's cycle count). There is no QEMU2 leg -- handback was removed.
10	//
11	// Requires built artifacts (qemu, vsim, plugin, the fixture). Run by
12	// tests/andes_sim/test_andes_sim_f6.sh. ELF overridable via argv[1].
13	#include <cstdio>
14	#include <string>
15	#include <vector>
16	
17	#include "engine_registry.hpp"
18	#include "plan.hpp"
19	#include "repo_root.hpp"
20	#include "run_plan.hpp"
21	#include "test_check.hpp"
22	
23	using namespace andes_sim;
24	
25	int main(int argc, char** argv) {
26	  const std::string elf =
27	      argc > 1 ? std::string(argv[1])
28	               : (repo_root() / "tests" / "fixtures" / "handoff_roundtrip.elf")
29	                     .string();
30	
31	  const Discovery disc = discover_engines();
32	
33	  // Pick the first cycle-accurate engine that can play the accurate leg.
34	  const EngineDescriptor* vsim = nullptr;
35	  for (const EngineDescriptor& e : disc.engines)
36	    if (e.type == "verilator" && e.invoke_for("accurate-leg")) {
37	      vsim = &e;
38	      break;
39	    }
40	  CHECK(vsim != nullptr);
41	  if (!vsim) return andes_sim::test::report("plan-itest");
42	
43	  std::printf("[f6-itest] elf=%s engine=%s\n", elf.c_str(), vsim->id.c_str());
44	
45	  Plan plan;
46	  plan.elf = elf;
47	  plan.mem_size = 128LL * 1024 * 1024;  // matches tests/e2e.sh SHARED_SIZE
48	  plan.steps = {
49	      {"qemu", "fast-leg", {"csr", {}}},
50	      {vsim->id, "accurate-leg", {"csr", {}}},
51	  };
52	
53	  const PlanResult r = run_plan(plan, disc.engines);
54	  if (!r.ok())
55	    std::fprintf(stderr, "[f6-itest] run_plan error: %s\n", r.error.c_str());
56	  CHECK(r.ok());
57	  CHECK(r.phases.size() == 2);
58	
59	  if (r.phases.size() == 2) {
60	    const unsigned long long q = r.phases[0].mcycle;
61	    const unsigned long long v = r.phases[1].mcycle;
62	    std::printf(
63	        "[f6-itest] qemu1 mcycle=%llu  vsim mcycle=%llu  kernel_cycles=%llu\n",
64	        q, v, v - q);
65	    CHECK(v > q);  // vsim measured a non-empty ROI
66	    CHECK(r.phases[1].minstret >= r.phases[0].minstret);
67	  }
68	
69	  return andes_sim::test::report("plan-itest");
70	}
