1	// The phase-plan grammar driven by run_plan (F6) -- the C++ analog of
2	// orchestrator/plan.py's Session/Step model, minus the dropped QEMU2 step.
3	//
4	// A Plan is a list of Steps; each Step names an engine (by id, resolved against
5	// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
6	// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
7	// order, threads the drained hybrid_state_v1 file forward, and returns each
8	// leg's mcycle/minstret. Under the no-QEMU2-handback design every F6 step
9	// drains, so the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg
10	// mcycle.
11	#ifndef ANDES_SIM_PLAN_HPP
12	#define ANDES_SIM_PLAN_HPP
13	
14	#include <map>
15	#include <string>
16	#include <vector>
17	
18	namespace andes_sim {
19	
20	// The ROI delimiter for a step. `kind` is csr|pc|icount|simpoint; `params`
21	// carries kind-specific values (e.g. icount=N, enter_pc, exit_pc) that F9 maps
22	// onto trigger args. F6 only exercises the default csr case (no params).
23	struct Trigger {
24	  std::string kind;
25	  std::map<std::string, std::string> params;
26	};
27	
28	// One leg of a plan: which engine, which invoke role, under which trigger.
29	struct Step {
30	  std::string engine_id;  // "qemu" | "verilator:ax45mpv_premium"
31	  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
32	  Trigger trigger;
33	};
34	
35	// A whole hybrid run. Every step loads `elf`; the shared mmap (`mem_size`
36	// bytes, at `mmap_path` or allocated by run_plan when empty) survives across
37	// every leg so memory threads through.
38	struct Plan {
39	  std::string elf;          // path to the ELF every leg launches
40	  long long mem_size = 0;   // shared-mmap size in bytes
41	  std::string mmap_path;    // "" => run_plan allocates one (F5) and owns it
42	  std::vector<Step> steps;
43	};
44	
45	// What one drain step measured (read back from its state file).
46	struct PhaseResult {
47	  unsigned long long mcycle = 0;
48	  unsigned long long minstret = 0;
49	};
50	
51	// Aggregate outcome. `error` empty => every step matched its expected exit and
52	// drained a valid state file; `phases` then holds one entry per step in order.
53	struct PlanResult {
54	  std::string error;
55	  std::vector<PhaseResult> phases;
56	  bool ok() const { return error.empty(); }
57	};
58	
59	}  // namespace andes_sim
60	
61	#endif  // ANDES_SIM_PLAN_HPP
