68	// Ask one binary to describe itself: try `<bin> --describe`, else read the
69	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
70	// a human-readable note in `warn`.
71	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
72	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
73	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
74	    json::Parsed p = json::parse(r.out);
75	    if (p.ok) {
76	      std::string err = descriptor_from_json(p.value, d);
77	      if (err.empty()) {
78	        d.bin_path = bin.string();
79	        d.source = "--describe";
80	        return true;
81	      }
82	      warn = bin.string() + ": --describe JSON invalid: " + err;
83	    } else {
84	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
85	    }
86	  }
87	
88	  fs::path sidecar = bin;
89	  sidecar += ".json";
90	  std::error_code ec;
91	  if (fs::exists(sidecar, ec)) {
92	    json::Parsed p = json::parse(read_file(sidecar));
93	    if (p.ok) {
94	      EngineDescriptor sd;
95	      std::string err = descriptor_from_json(p.value, sd);
96	      if (err.empty()) {
97	        sd.bin_path = bin.string();
98	        sd.source = "sidecar";
99	        d = std::move(sd);
100	        return true;
101	      }
102	      warn = sidecar.string() + ": invalid descriptor: " + err;
103	    } else {
104	      warn = sidecar.string() + ": not JSON: " + p.error;
105	    }
106	  }
107	
108	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
109	  return false;
110	}
111	
112	// `prefix` filters candidate basenames; empty accepts any executable. The
113	// default verilator/build scan passes "sim_"; a user-curated engines dir passes
114	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
115	// lives in the call site, not in this engine-agnostic scanner.
116	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
117	              std::set<std::string>& seen) {
118	  std::error_code ec;
119	  if (!fs::is_directory(dir, ec)) return;
120	
121	  std::vector<fs::path> entries;
122	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
123	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
124	
125	  for (const fs::path& p : entries) {
126	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
127	    if (!is_executable_file(p)) continue;
128	    EngineDescriptor d;
129	    std::string warn;
130	    if (describe_one(p, d, warn)) {
131	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
132	    } else if (!warn.empty()) {
133	      out.warnings.push_back(warn);
134	    }
135	  }
136	}
137	
138	}  // namespace
139	
140	Discovery discover_engines() {
141	  Discovery out;
142	  std::set<std::string> seen;
143	
144	  EngineDescriptor qemu = builtin_qemu();
145	  seen.insert(qemu.id);
146	  out.engines.push_back(std::move(qemu));
147	
148	  if (const char* env = std::getenv("ANDES_SIM_ENGINES_DIR"); env && *env) {
149	    std::stringstream ss(env);
150	    std::string dir;
151	    while (std::getline(ss, dir, ':'))
152	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
153	  } else {
154	    scan_dir(repo_root() / "verilator" / "build", /*prefix=*/"sim_", out, seen);
155	  }
156	  return out;
157	}
